package analysis

// doc_quality_test.go — port of tests/unit/test_doc_scoring.py plus
// whole-seam byte pins for ScoreDocs. Every corpus fixture below (input and
// expected output) was generated by RUNNING the Python reference
// (`score_docs(build_score_docs_inputs(pages=...))` → json.dumps) in this
// worktree, so every asserted literal doubles as a parity fixture; the
// unit-level numbers are transcribed verbatim from the Python test file.

import (
	"encoding/json"
	"testing"

	"github.com/yeaboi-ai/yeaboi/go/internal/pysem"
)

// Fixtures shared with tests/unit/test_doc_scoring.py (same literals).
const (
	docPlainTwoSentences = "The team ships code every day. We check the logs after lunch."
	docDense             = "The deployment process requires careful preparation. " +
		"Every developer should verify the configuration before release."
	docStructured = "# Setup Guide\n\n" +
		"Purpose: install the tool.\n\n" +
		"- Run the installer.\n" +
		"- Check the output.\n\n" +
		"## Notes\n\n" +
		"Owner: Jane\n"
	docCodeFence  = "```\nkubernetes_deployment_reconciliation_orchestrator --enable-multiregional-failover\n```\n"
	docShortProse = "Run the deploy. It is safe."
	docRich       = "# Deploy Runbook\n\n" +
		"Purpose: ship the API safely.\n\n" +
		"Owner: Jane\n\n" +
		"- Run the deploy script.\n" +
		"- Verify the dashboards.\n\n" +
		"```\nrelease_orchestrator --region all\n```\n\n" +
		"Generated with Claude Code.\n"
)

// docAsset mirrors the Python test's _asset fixture: base dict + overrides.
func docAsset(overrides ...any) *pysem.Obj {
	a := obj(
		"platform", "notion",
		"title", "Page",
		"clarity", json.Number("80.0"),
		"usefulness", json.Number("80.0"),
		"url", "",
	)
	for i := 0; i+1 < len(overrides); i += 2 {
		a.Set(overrides[i].(string), overrides[i+1])
	}
	return a
}

func TestDocCountSyllables(t *testing.T) {
	cases := []struct {
		word string
		want int
	}{
		{"hello", 2},
		{"banana", 3},
		{"beautiful", 3}, // eau + i + u — groups, not real syllables
		{"cake", 1},
		{"create", 1}, // "ea" collapses, then the final e trims
		{"queue", 1},  // "ueue" is a single group; n==1 so no trim
		{"the", 1},    // ends in e but n == 1 → no trim
		{"strength", 1},
		{"rhythm", 1}, // y counts as a vowel
		{"", 1},
		{"bcd", 1},
		{"İ", 1}, // İ lowers to "i"+U+0307; [aeiouy]+ still finds the i
	}
	for _, c := range cases {
		if got := countSyllables(c.word); got != c.want {
			t.Errorf("countSyllables(%q) = %d, want %d", c.word, got, c.want)
		}
	}
}

func TestDocClarityMetricsExactValues(t *testing.T) {
	cases := []struct {
		name string
		text string
		want clarityMetricsResult
	}{
		{"empty", "", clarityMetricsResult{}},
		// 12 words, 2 sentences, 15 syllables: 206.835 − 1.015·6.0 −
		// 84.6·(15/12) = 94.995 → 95.0. No structure bonus.
		{"plain", docPlainTwoSentences, clarityMetricsResult{12, 2, 6.0, 0.0, 0, false, false, 95.0}},
		// Real words, real sentences — Flesch goes below 0 and clamps.
		{"dense", docDense, clarityMetricsResult{14, 2, 7.0, 0.0, 0, false, false, 0.0}},
		// Flesch 73.3 + 4 (headings) + 3 (lists) = 80.3.
		{"structured", docStructured, clarityMetricsResult{15, 4, 3.8, 0.0, 2, true, false, 80.3}},
		{"code fence stripped", docCodeFence + docShortProse, clarityMetricsResult{6, 2, 3.0, 0.0, 0, false, true, 100.0}},
		{"short prose alone", docShortProse, clarityMetricsResult{6, 2, 3.0, 0.0, 0, false, false, 100.0}},
		// Python's unicode \s matches U+00A0, so the NBSP ends the sentence —
		// the #1 divergence risk for this port.
		{"nbsp splits", "One two three. Four five six.", clarityMetricsResult{6, 2, 3.0, 0.0, 0, false, false, 100.0}},
		{"punctuation only", "?! ... !!!", clarityMetricsResult{}},
		// \d is unicode Nd, so "٣." is a list marker; the bare "٣" before the
		// first ". " also splits off as its own (word-free) sentence.
		{"arabic-indic list", "٣. First step\n٤. Second step\nSome prose here.",
			clarityMetricsResult{7, 3, 2.3, 0.0, 0, true, false, 100.0}},
	}
	for _, c := range cases {
		if got := clarityMetrics(c.text); got != c.want {
			t.Errorf("%s: clarityMetrics = %+v, want %+v", c.name, got, c.want)
		}
	}
}

func TestDocClarityMetricsHeadingIndentAllowsAtMostThreeSpaces(t *testing.T) {
	if got := clarityMetrics("   # ok heading\n\nSome words here now.").headingCount; got != 1 {
		t.Errorf("3-space indent headingCount = %d, want 1", got)
	}
	if got := clarityMetrics("    # too deep\n\nSome words here now.").headingCount; got != 0 {
		t.Errorf("4-space indent headingCount = %d, want 0", got)
	}
}

func TestDocClarityMetricsBulletGlyphCountsAsAList(t *testing.T) {
	if !clarityMetrics("• item one\nSome words here now.").hasLists {
		t.Error("bullet glyph hasLists = false, want true")
	}
}

func TestDocClarityMetricsLongSentenceBoundaryIsStrictlyMoreThan25Words(t *testing.T) {
	words := ""
	for i := 0; i < 25; i++ {
		if i > 0 {
			words += " "
		}
		words += "word"
	}
	if got := clarityMetrics(words + ". Short one.").longSentencePct; got != 0.0 {
		t.Errorf("25-word sentence longSentencePct = %v, want 0.0", got)
	}
	if got := clarityMetrics(words + " word. Short one.").longSentencePct; got != 50.0 {
		t.Errorf("26-word sentence longSentencePct = %v, want 50.0", got)
	}
}

func TestDocClarityMetricsPeriodFollowedDirectlyByALetterDoesNotSplit(t *testing.T) {
	m := clarityMetrics("One two three.Four five six.")
	if m.sentenceCount != 1 || m.avgSentenceWords != 6.0 {
		t.Errorf("got (%d, %v), want (1, 6.0)", m.sentenceCount, m.avgSentenceWords)
	}
}

func TestDocClarityMetricsWordTokenisationIsASCII(t *testing.T) {
	// İ is outside [A-Za-z'], so "VERİFY" tokenizes as two words: 5 total.
	if got := clarityMetrics("VERİFY the output now.").wordCount; got != 5 {
		t.Errorf("VERİFY wordCount = %d, want 5", got)
	}
	if got := clarityMetrics("Don't stop now.").wordCount; got != 3 {
		t.Errorf("apostrophe wordCount = %d, want 3", got)
	}
}

func TestDocUsefulnessMetricsExactValues(t *testing.T) {
	cases := []struct {
		name string
		text string
		want usefulnessMetricsResult
	}{
		{"fully useful", docStructured, usefulnessMetricsResult{100.0, true, true, true, true}},
		{"empty keeps base", "", usefulnessMetricsResult{20.0, false, false, false, false}},
		{"each signal adds twenty", "VERIFY the output now.", usefulnessMetricsResult{40.0, false, true, false, false}},
		// str.lower() maps İ → "i"+U+0307; the combining dot sits inside
		// "veri̇fy" so \bverify\b never matches (ASCII lowering would diverge).
		{"turkish i defeats verbs", "VERİFY the output now.", usefulnessMetricsResult{20.0, false, false, false, false}},
	}
	for _, c := range cases {
		if got := usefulnessMetrics(c.text); got != c.want {
			t.Errorf("%s: usefulnessMetrics = %+v, want %+v", c.name, got, c.want)
		}
	}
}

func TestDocUsefulnessMetricsOwnerLineShapes(t *testing.T) {
	owned := []string{
		"Owner: Jane", "**Owner**: Jane", "Owner | Jane", "maintainer - Jane",
		"responsible: Ops", "CONTACT: someone",
		"Owner\n\n: Jane", // \s* after the keyword crosses blank lines
	}
	for _, text := range owned {
		if !usefulnessMetrics(text).owned {
			t.Errorf("owned(%q) = false, want true", text)
		}
	}
	notOwned := []string{
		"| Owner | Jane |",       // the leading pipe defeats the anchor — deliberate miss
		"The owner is Jane: yes", // keyword must start the line
	}
	for _, text := range notOwned {
		if usefulnessMetrics(text).owned {
			t.Errorf("owned(%q) = true, want false", text)
		}
	}
}

func TestDocUsefulnessMetricsActionableAndPurposeBoundaries(t *testing.T) {
	for _, text := range []string{"Take the next step now.", "We must decide soon.", "decision"} {
		if !usefulnessMetrics(text).actionable {
			t.Errorf("actionable(%q) = false, want true", text)
		}
	}
	// "next steps" fails \b after "step"; "resolved" never matches "resolve".
	for _, text := range []string{"Next steps for the team.", "resolved"} {
		if usefulnessMetrics(text).actionable {
			t.Errorf("actionable(%q) = true, want false", text)
		}
	}
	for _, text := range []string{"TL;DR: yes", "The why matters."} {
		if !usefulnessMetrics(text).hasPurpose {
			t.Errorf("hasPurpose(%q) = false, want true", text)
		}
	}
	if usefulnessMetrics("goals").hasPurpose { // "goal" bounded, "goals" escapes
		t.Error("hasPurpose(goals) = true, want false")
	}
}

func TestDocHasAiDisclosure(t *testing.T) {
	cases := []struct {
		text string
		want bool
	}{
		{"Generated with Claude Code", true},
		{"Generated with [Claude Code](https://claude.com/claude-code)", true},
		{"GENERATED WITH CLAUDE CODE", true},
		{"co-authored-by: claude", true},
		// The claude marker demands the literal "claude code" — the shorter
		// disclosure fails the marker gate even though the context matches.
		{"Generated with Claude", false},
		{"Co-Authored-By: Claude <noreply@anthropic.com>", true},
		// \s+ in the context is unicode: the NBSP inside "Drafted with"
		// still matches; the marker is satisfied by noreply@anthropic.com.
		{"Drafted with help from tooling. Contact noreply@anthropic.com for details.", true},
		{"Drafted with help from tooling.", false}, // context without a marker
		{"AI tooling guide. Example trailer address: copilot@github.com. See https://claude.com/claude-code.", false},
		{"", false},
	}
	for _, c := range cases {
		if got := hasAiDisclosure(c.text); got != c.want {
			t.Errorf("hasAiDisclosure(%q) = %v, want %v", c.text, got, c.want)
		}
	}
}

