	assertDump(t, analysePageAsset(obj()), `{"title": "Untitled", "platform": "", "clarity": 0.0, "usefulness": 20.0, "owned": false, "actionable": false, "structured": false, "has_code_blocks": false, "marked": false, "url": "", "key": "", "container": "", "version": ""}`)
