func TestDocAnalysePageAssetVersionFallsBackToTimestamp(t *testing.T) {
	if got := analysePageAsset(obj("timestamp", "2026-01-01")).Get("version"); got != "2026-01-01" {
		t.Errorf("version = %v, want 2026-01-01", got)
	}
}

func TestDocAnalysePageAssetTitleTruncatesTo80CodePoints(t *testing.T) {
	long := ""
	for i := 0; i < 100; i++ {
		long += "x"
	}
	if got := analysePageAsset(obj("title", long)).Get("title"); got != long[:80] {
		t.Errorf("title = %v, want 80 x's", got)
	}
	// The "Untitled" default applies only when the key is ABSENT: a present
	// empty title stays "".
	if got := analysePageAsset(obj("title", "")).Get("title"); got != "" {
		t.Errorf("empty title = %v, want \"\"", got)
	}
}

func TestDocAggregateDocAssetsEmptyReturnsDefaultSignal(t *testing.T) {
	sig := aggregateDocAssets([]any{})
	if sig.pagesScanned != 0 || sig.avgClarity != 0.0 || sig.avgUsefulness != 0.0 ||
		len(sig.platforms) != 0 || len(sig.perPlatform) != 0 || len(sig.flagged) != 0 {
		t.Errorf("empty aggregate = %+v, want zero signal", sig)
	}
}

func TestDocAggregateDocAssetsAveragesRoundHalfToEven(t *testing.T) {
	down := aggregateDocAssets([]any{
		docAsset("clarity", json.Number("70.0"), "usefulness", json.Number("80.0")),
		docAsset("clarity", json.Number("70.5"), "usefulness", json.Number("80.5")),
	})
	if down.avgClarity != 70.2 { // 70.25 → .2 (even), not .3
		t.Errorf("avgClarity = %v, want 70.2", down.avgClarity)
	}
	if down.avgUsefulness != 80.2 { // 80.25 → .2
		t.Errorf("avgUsefulness = %v, want 80.2", down.avgUsefulness)
	}
	up := aggregateDocAssets([]any{
		docAsset("clarity", json.Number("70.0")),
		docAsset("clarity", json.Number("71.5")),
	})
	if up.avgClarity != 70.8 { // 70.75 → .8 (even)
		t.Errorf("avgClarity = %v, want 70.8", up.avgClarity)
	}
}

func TestDocAggregateDocAssetsBandingBoundariesAreExact(t *testing.T) {
	bands := func(clarity string) [3]int64 {
		sig := aggregateDocAssets([]any{docAsset("clarity", json.Number(clarity), "usefulness", json.Number("100.0"))})
		return [3]int64{sig.clearPages, sig.mixedPages, sig.unclearPages}
	}
	if got := bands("60.0"); got != [3]int64{1, 0, 0} { // >= 60 is clear
		t.Errorf("bands(60.0) = %v", got)
	}
	if got := bands("59.9"); got != [3]int64{0, 1, 0} {
		t.Errorf("bands(59.9) = %v", got)
	}
	if got := bands("40.0"); got != [3]int64{0, 1, 0} { // 40 is still mixed
		t.Errorf("bands(40.0) = %v", got)
	}
	if got := bands("39.9"); got != [3]int64{0, 0, 1} {
		t.Errorf("bands(39.9) = %v", got)
	}
}

func TestDocAggregateDocAssetsFlaggedOrderingClarityThenUsefulnessDedupedByTitle(t *testing.T) {
	assets := []any{
		docAsset("title", "Clear", "clarity", json.Number("80.0"), "usefulness", json.Number("100.0")),
		docAsset("title", "Worst", "clarity", json.Number("10.0"), "usefulness", json.Number("100.0")),
		docAsset("title", "Bad", "clarity", json.Number("30.0"), "usefulness", json.Number("100.0")),
		docAsset("title", "Useless", "clarity", json.Number("90.0"), "usefulness", json.Number("20.0")),
		docAsset("title", "LessUseless", "clarity", json.Number("90.0"), "usefulness", json.Number("40.0")),
		docAsset("title", "Worst", "clarity", json.Number("15.0"), "usefulness", json.Number("10.0")), // dupe title → deduped
	}
	want := [][2]string{
		{"Worst", "clarity 10/100 — dense or long-winded"},
		{"Bad", "clarity 30/100 — dense or long-winded"},
		{"Useless", "usefulness 20/100 — missing purpose, ownership, or actions"},
		{"LessUseless", "usefulness 40/100 — missing purpose, ownership, or actions"},
	}
	got := aggregateDocAssets(assets).flagged
	if len(got) != len(want) {
		t.Fatalf("flagged = %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Errorf("flagged[%d] = %v, want %v", i, got[i], want[i])
		}
	}
}

func TestDocAggregateDocAssetsPerPlatformSortsByCountDescThenName(t *testing.T) {
	sig := aggregateDocAssets([]any{
		docAsset("platform", "notion"),
		docAsset("platform", "confluence"),
		docAsset("platform", "notion"),
		docAsset("platform", "wiki"),
	})
	assertDump(t, sig.perPlatform, `[["notion", 2], ["confluence", 1], ["wiki", 1]]`)
	// platforms_scanned keeps first-seen order, unsorted.
	assertDump(t, stringsAsAny(sig.platforms), `["notion", "confluence", "wiki"]`)
}

