func docFindingsAssets() []any {
	return []any{
		obj("platform", "confluence", "title", "Dense Wall", "clarity", json.Number("30.0"),
			"usefulness", json.Number("40.0"), "url", "https://x/p2"),
		obj("platform", "notion", "title", "Fine", "clarity", json.Number("75.0"),
			"usefulness", json.Number("80.0"), "url", "https://x/p3"),
		obj("platform", "notion", "title", "HalfRound", "clarity", json.Number("59.5"),
			"usefulness", json.Number("58.5"), "url", ""),
	}
}

func TestDocFindingsIDsCategoriesAndOrderingAreExact(t *testing.T) {
	findings := docFindings(docFindingsAssets())
	wantIDs := []string{
		"confluence:Dense Wall:clarity",
		"confluence:Dense Wall:usefulness",
		"notion:HalfRound:clarity",
		"notion:HalfRound:usefulness",
	}
	if len(findings) != len(wantIDs) {
		t.Fatalf("len(findings) = %d, want %d", len(findings), len(wantIDs))
	}
	for i, id := range wantIDs {
		if got := pysem.AsObj(findings[i]).Get("id"); got != id {
			t.Errorf("findings[%d] id = %v, want %q", i, got, id)
		}
	}
}

func TestDocFindingsClarityAndUsefulnessFindingsAreExact(t *testing.T) {
	findings := docFindings(docFindingsAssets())
	// {**base, "id": …} → the four base keys lead every finding dict.
	assertDump(t, findings[0], `{"link": "https://x/p2", "affected_scope": ["confluence:Dense Wall"], "owner_role": "Documentation owner", "confidence": "high", "id": "confluence:Dense Wall:clarity", "category": "clarity", "title": "Rewrite dense documentation", "detail": "Lead with the outcome, shorten sentences, and split the page with descriptive headings and lists.", "priority": "high", "impact": "Makes operational knowledge faster to understand and use.", "evidence": "Dense Wall scored 30/100 for clarity.", "next_steps": ["Rewrite the summary and longest sections.", "Have a target reader validate the instructions."], "effort": "small", "completion_check": "A target reader can identify the purpose and required action without author help."}`)
	assertDump(t, findings[1], `{"link": "https://x/p2", "affected_scope": ["confluence:Dense Wall"], "owner_role": "Documentation owner", "confidence": "high", "id": "confluence:Dense Wall:usefulness", "category": "usefulness", "title": "Add purpose, ownership, and actions", "detail": "State why the page exists, who maintains it, and the concrete procedure or decision it supports.", "priority": "high", "impact": "Turns descriptive prose into maintainable, actionable team knowledge.", "evidence": "Dense Wall scored 40/100 for usefulness.", "next_steps": ["Add purpose and owner fields.", "Add verified steps, decisions, or next actions."], "effort": "small", "completion_check": "The page names an owner and provides a verifiable action or decision."}`)
}

