func TestDocPrioritizeActionsGroupsByCategoryAndTitleWithPagesSuffix(t *testing.T) {
	findings := docFindings([]any{
		obj("platform", "confluence", "title", "Dense Wall", "clarity", json.Number("30.0"),
			"usefulness", json.Number("40.0"), "url", "u2"),
		obj("platform", "notion", "title", "HalfRound", "clarity", json.Number("59.5"),
			"usefulness", json.Number("58.5"), "url", ""),
	})
	actions := prioritizeDocActions(findings)
	if len(actions) != 2 {
		t.Fatalf("len(actions) = %d, want 2", len(actions))
	}
	for i, want := range [][2]any{
		{"confluence:Dense Wall:clarity", int64(2)},
		{"confluence:Dense Wall:usefulness", int64(2)},
	} {
		a := pysem.AsObj(actions[i])
		if a.Get("id") != want[0] || a.Get("breadth") != want[1] {
			t.Errorf("actions[%d] = (%v, %v), want %v", i, a.Get("id"), a.Get("breadth"), want)
		}
	}
	// The exemplar is the FIRST finding of each group; scopes are sorted and
	// the suffix says "pages" (code_health says "repositories" — deliberate).
	first := pysem.AsObj(actions[0])
	assertDump(t, first.Get("affected_scope"), `["confluence:Dense Wall", "notion:HalfRound"]`)
	if got := first.Get("evidence"); got != "Dense Wall scored 30/100 for clarity. Affects 2 pages." {
		t.Errorf("evidence = %v", got)
	}
	if got := first.Get("link"); got != "u2" {
		t.Errorf("link = %v, want u2", got)
	}
}

func TestDocPrioritizeActionsSinglePageActionKeepsEvidenceVerbatim(t *testing.T) {
	actions := prioritizeDocActions(docFindings([]any{
		docAsset("title", "Solo", "clarity", json.Number("10.0"), "usefulness", json.Number("100.0")),
	}))
	if len(actions) != 1 {
		t.Fatalf("len(actions) = %d, want 1", len(actions))
	}
	a := pysem.AsObj(actions[0])
	if a.Get("evidence") != "Solo scored 10/100 for clarity." || a.Get("breadth") != int64(1) {
		t.Errorf("action = (%v, %v)", a.Get("evidence"), a.Get("breadth"))
	}
}

func TestDocPrioritizeActionsSortsByPriorityThenBreadthWithNoTitleTiebreak(t *testing.T) {
	// Wider group wins within a priority; equal keys keep grouping insertion
	// order (stable sort) — there is NO title tiebreak here, unlike
	// code_health.PrioritizeActions.
	findings := []any{
		stubFinding("clarity", "Zulu", "high", []any{"a"}, "E."),
		stubFinding("usefulness", "Alpha", "high", []any{"b"}, "E."),
		stubFinding("usefulness", "Alpha", "high", []any{"c"}, "E."),
		stubFinding("misc", "Low", "low", []any{"d"}, "E."),
		stubFinding("misc", "Odd", "urgent", []any{"e"}, "E."), // unknown priority → rank 9, sorts last
	}
	actions := prioritizeDocActions(findings)
	wantTitles := []string{"Alpha", "Zulu", "Low", "Odd"}
	if len(actions) != len(wantTitles) {
		t.Fatalf("len(actions) = %d, want %d", len(actions), len(wantTitles))
	}
	for i, title := range wantTitles {
		if got := pysem.AsObj(actions[i]).Get("title"); got != title {
			t.Errorf("actions[%d] title = %v, want %q", i, got, title)
		}
	}
}

func TestDocPrioritizeActionsFalsyScopesAreKeptNotDropped(t *testing.T) {
	// Unlike code_health, the scope set has no `if scope` filter: an empty
	// scope survives and inflates breadth. Pinned divergence.
	findings := []any{
		stubFinding("c", "T", "high", []any{"b", "", "a"}, "E."),
		stubFinding("c", "T", "high", []any{"b"}, "ignored"),
	}
	actions := prioritizeDocActions(findings)
	if len(actions) != 1 {
		t.Fatalf("len(actions) = %d, want 1", len(actions))
	}
	action := pysem.AsObj(actions[0])
	assertDump(t, action.Get("affected_scope"), `["", "a", "b"]`)
	if action.Get("breadth") != int64(3) || action.Get("evidence") != "E. Affects 3 pages." {
		t.Errorf("action = (%v, %v)", action.Get("breadth"), action.Get("evidence"))
	}
}

func TestDocInsightsFlaggedSamplesProduceExactActionLedInsights(t *testing.T) {
	sig := docSignal{pagesScanned: 6, ownedPages: 2, actionablePages: 3, avgUsefulness: 48.4}
	samples := []any{obj("platform", "notion", "title", "Dense", "clarity", json.Number("20.0"),
		"usefulness", json.Number("20.0"), "url", "https://u/1")}
	assertDump(t, fallbackDocQualityInsights(sig, samples), `{"start": [{"title": "Rewrite dense documentation", "detail": "Lead with the outcome, shorten sentences, and split the page with descriptive headings and lists.", "evidence": "Dense scored 20/100 for clarity.", "link": "https://u/1"}, {"title": "Add purpose, ownership, and actions", "detail": "State why the page exists, who maintains it, and the concrete procedure or decision it supports.", "evidence": "Dense scored 20/100 for usefulness.", "link": "https://u/1"}], "stop": [{"title": "Stop publishing ownerless guidance", "detail": "Every operational page should name a maintainer and a concrete validation step.", "evidence": "4 page(s) lack an owner signal"}], "keep": [{"title": "Keep actionable pages current", "detail": "Preserve the pages that already combine clear structure with executable guidance.", "evidence": "3 actionable page(s) found"}], "try": [{"title": "Use a shared documentation template", "detail": "Start pages with purpose, owner, last-reviewed date, procedure, and verification.", "evidence": "Average usefulness 48/100"}]}`)
}

func TestDocInsightsNoActionsFallsBackToExactBaseline(t *testing.T) {
	// 71.5 → "72" and 62.5 → "62": :.0f rounds half to even both ways.
	sig := docSignal{pagesScanned: 2, avgClarity: 71.5, avgUsefulness: 62.5}
	assertDump(t, fallbackDocQualityInsights(sig, nil), `{"start": [{"title": "Set a documentation quality baseline", "detail": "Use purpose, owner, procedure, and verification fields for every shared page.", "evidence": "2 page(s) scanned"}], "stop": [{"title": "Stop relying on implicit ownership", "detail": "Name a maintainer so readers know who can verify and update the page.", "evidence": "Ownership is assessed explicitly in the new documentation score."}], "keep": [{"title": "Keep clear documentation patterns", "detail": "Continue using concise sections and concrete procedures.", "evidence": "Average clarity 72/100"}], "try": [{"title": "Review documentation with a target reader", "detail": "Ask someone other than the author to execute or explain the documented process.", "evidence": "Average usefulness 62/100"}]}`)
}

func TestDocInsightsHealthySamplesUseTheBaselineBranch(t *testing.T) {
	out := fallbackDocQualityInsights(docSignal{pagesScanned: 1},
		[]any{docAsset("title", "Good", "clarity", json.Number("80.0"), "usefulness", json.Number("80.0"))})
	start, _ := out.Get("start").([]any)
	if got := pysem.AsObj(start[0]).Get("title"); got != "Set a documentation quality baseline" {
		t.Errorf("start[0] title = %v", got)
	}
}

func TestDocInsightsGroupingMakesTheCapUnreachable(t *testing.T) {
	// Five flagged pages collapse into ONE clarity action (same
	// category+title), so start never approaches docInsightMaxItems.
	samples := []any{}
	for i := 0; i < 5; i++ {
		samples = append(samples, docAsset(
			"title", "P"+string(rune('0'+i)),
			"clarity", json.Number(pysem.FloatRepr(10.0+float64(i))),
			"usefulness", json.Number("100.0")))
	}
	out := fallbackDocQualityInsights(docSignal{pagesScanned: 5}, samples)
	start, _ := out.Get("start").([]any)
	if len(start) != 1 {
		t.Fatalf("len(start) = %d, want 1", len(start))
	}
	if got := pysem.AsObj(start[0]).Get("evidence"); got != "P0 scored 10/100 for clarity. Affects 5 pages." {
		t.Errorf("evidence = %v", got)
	}
}

func TestDocInsightsItemKeyOrderAndLinkPlacement(t *testing.T) {
	// Empty url → no "link" key; truthy url appends "link" AFTER evidence.
	noLink := fallbackDocQualityInsights(docSignal{pagesScanned: 1},
		[]any{docAsset("title", "Dense", "clarity", json.Number("20.0"), "usefulness", json.Number("100.0"))})
	start, _ := noLink.Get("start").([]any)
	keys := pysem.AsObj(start[0]).Keys()
	if len(keys) != 3 || keys[0] != "title" || keys[1] != "detail" || keys[2] != "evidence" {
		t.Errorf("keys = %v, want [title detail evidence]", keys)
	}
	withLink := fallbackDocQualityInsights(docSignal{pagesScanned: 1},
		[]any{docAsset("title", "Dense", "clarity", json.Number("20.0"), "usefulness", json.Number("100.0"),
			"url", "https://u/1")})
	start, _ = withLink.Get("start").([]any)
	keys = pysem.AsObj(start[0]).Keys()
	if len(keys) != 4 || keys[3] != "link" {
		t.Errorf("keys = %v, want [title detail evidence link]", keys)
	}
}

func TestDocInsightsOwnerlessCountClampsAtZero(t *testing.T) {
	out := fallbackDocQualityInsights(docSignal{pagesScanned: 1, ownedPages: 5},
		[]any{docAsset("title", "Dense", "clarity", json.Number("20.0"), "usefulness", json.Number("100.0"))})
	stop, _ := out.Get("stop").([]any)
	if got := pysem.AsObj(stop[0]).Get("evidence"); got != "0 page(s) lack an owner signal" {
		t.Errorf("evidence = %v", got)
	}
}

