func docPagesFrom(t *testing.T, input string) []any {
	t.Helper()
	decoded, err := pysem.DecodeOrdered([]byte(input))
	if err != nil {
		t.Fatalf("decode input: %v", err)
	}
	pages, _ := pysem.AsObj(decoded).Get("pages").([]any)
	return pages
}

func TestDocScoreDocsWholeSeamPins(t *testing.T) {
	cases := []struct {
		name  string
		input string
		want  string
	}{
		// A cached asset passed through verbatim (scrambled key order kept), a
		// fresh rich page, an NBSP + AI-disclosure page, a Turkish İ page, an
		// Arabic-Indic list page, a whitespace-only page (dropped), a page with
		// no title key ("Untitled") and one with an empty title (stays "").
		{"rich mixed corpus", scoreDocsRichInput, scoreDocsRichWant},
		{"empty pages", scoreDocsEmptyInput, scoreDocsEmptyWant},
		{"four pages small sample", scoreDocsFourInput, scoreDocsFourWant},
		{"five pages full sample", scoreDocsFiveInput, scoreDocsFiveWant},
		// Five flagged pages collapse to one breadth-5 action with the
		// " Affects 5 pages." suffix riding into the insights.
		{"five flagged pages", scoreDocsFlagged5Input, scoreDocsFlagged5Want},
		// 70.25 → 70.2 and 80.25 → 80.2: banker's rounding on the averages.
		{"half-even averages", scoreDocsHalfEvenInput, scoreDocsHalfEvenWant},
	}
	for _, c := range cases {
		got := pysem.JSONDumps(ScoreDocs(docPagesFrom(t, c.input)))
		if got != c.want {
			t.Errorf("%s mismatch\n got: %s\nwant: %s", c.name, got, c.want)
		}
	}
}

